/* =====================================================================
   OUTCOME  |  partidas em rodadas, tela de configuração, abertura animada, histórico (veja UPDATES), celular
   WASD/Setas mover | Mouse mirar | Clique socar/atirar | E pegar arma
   R recarregar | Q sacar/guardar arma | G ou botão direito arremessar arma | C cobertura | H hitbox | Esc menu
   ===================================================================== */
let RES = devicePixelRatio || 1, RES_MIN = 0.75, _slow = 0;
const canvas = document.getElementById('game');
let ctx = canvas.getContext('2d');
const TAU = Math.PI * 2;
const rnd = (a, b) => a + Math.random() * (b - a);
const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
const angDiff = (a, b) => ((a - b + Math.PI * 3) % TAU) - Math.PI;
const approach = (v, t, a) => v < t ? Math.min(v + a, t) : Math.max(v - a, t);
const easeOutExpo = t => t >= 1 ? 1 : 1 - Math.pow(2, -10 * t);
const easeInOut = t => t < .5 ? 2*t*t : 1 - Math.pow(-2*t + 2, 2) / 2;

/* ------------------------------ CONFIG -------------------------------- */
const C = {
  moveSpeed: 250, accel: 2800, friction: 2400,
  punchDamage: 15, punchCooldown: .17, punchDuration: .24, comboWindow: .55,
  reach: 40, heavyReach: 54, lunge: 150, heavyLunge: 260, hitRadius: 13,
  shoulder: 12.5, r: 15,
  holdReach: 44,   // distância da mão direita ao centro do corpo ao mirar (braço totalmente esticado)
  throwSpeed: 900, throwDrag: 2, throwStun: 2.5, throwMinHit: 240,   // arremesso de arma: velocidade, atrito, tempo de nocaute, velocidade mínima p/ nocautear
};
/* Deslize tático (tecla DESLIZAR, ESPAÇO): correndo, o personagem desliza rápido pelo chão. Nos primeiros instantes ele é invulnerável a tiros (I-frames) e passa por obstáculos baixos (tubulações e lixeiras). */
const SLIDE = { dur: .4, ifr: .26, cd: .9, speed: 760 };
const LOW = { pipe: 1, bin: 1 };   // obstáculos baixos que dá para atravessar deslizando
const iframes = f => f.slideT > 0 && f.slideT > SLIDE.dur - SLIDE.ifr;
const overLow = f => crates.some(c => LOW[c.k] && Math.hypot(f.x - clamp(f.x, c.x, c.x + c.w), f.y - clamp(f.y, c.y, c.y + c.h)) < f.r);
/* Cover de dupla altura: BAIXO (LOWC) deixa atirar por cima de perto; ALTO bloqueia tiros e visão por completo. Vidraças (glass) quebram com 2 tiros. */
const LOWC = { pipe: 1, bin: 1, wood: 1, dump: 1, lowwall: 1, counter: 1, lcrate: 1, sofa: 1 };
let glassShards = [];
const nearC = (o, c) => !!o && o.x !== undefined && Math.hypot(o.x - clamp(o.x, c.x, c.x + c.w), o.y - clamp(o.y, c.y, c.y + c.h)) < (o.r || 14) + 34;   // colado no obstáculo
const inSolid = (x, y) => crates.some(c => !LOWC[c.k] && x > c.x && x < c.x + c.w && y > c.y && y < c.y + c.h);
function shotHit(x, y, o) {   // obstáculo que para a bala em (x, y); o cover baixo não para quem atira colado nele
  for (const c of crates) if (x > c.x && x < c.x + c.w && y > c.y && y < c.y + c.h) { if (LOWC[c.k] && nearC(o, c)) continue; return c; }
  return null;
}
function glassHit(c, x, y) {
  c.hp = (c.hp === undefined ? 2 : c.hp) - 1;
  for (let i = 0; i < 5; i++) { const a = rnd(0, TAU); sparks.push({ x, y, vx: Math.cos(a) * 170, vy: Math.sin(a) * 170, life: .5 }); }
  if (c.hp <= 0) {
    const k = crates.indexOf(c); if (k >= 0) crates.splice(k, 1);
    for (let i = 0; i < 20; i++) glassShards.push({ x: c.x + rnd(0, c.w), y: c.y + rnd(0, c.h), a: rnd(0, TAU), s: rnd(3, 8) });
    for (let i = 0; i < 12; i++) { const a = rnd(0, TAU); sparks.push({ x: c.x + rnd(0, c.w), y: c.y + rnd(0, c.h), vx: Math.cos(a) * 230, vy: Math.sin(a) * 230, life: .7 }); }
    shake = Math.max(shake, 4);
  }
}
const DIFFS = [
  { name: 'FÁCIL',   hp: 50, speed: 140, err: .38, turn: 4,  dmg: .5,  burst: .6 },
  { name: 'NORMAL',  hp: 70, speed: 170, err: .22, turn: 6,  dmg: .7,  burst: 1 },
  { name: 'DIFÍCIL', hp: 90, speed: 200, err: .10, turn: 9,  dmg: .95, burst: 1.5 },
];

