/* Silhuetas laterais (estilo HUD do Kusan): voltadas para a DIREITA, cor única
   aplicada por quem desenha (drawSilhouette). Cada uma tem seu espaço w x h. */
const poly = pts => { ctx.beginPath(); pts.forEach(([x, y], i) => i ? ctx.lineTo(x, y) : ctx.moveTo(x, y)); ctx.closePath(); ctx.fill(); };
const rr = (x, y, w, h, r) => { ctx.beginPath(); ctx.roundRect(x, y, w, h, r); ctx.fill(); };
const guard = (x, y, r, lw = 2.2) => { ctx.lineWidth = lw; ctx.strokeStyle = ctx.fillStyle; ctx.beginPath(); ctx.arc(x, y, r, 0, Math.PI); ctx.stroke(); };
