function drawSilhouette(w, x, y, sc, flip) {
  const S = w.sil; ctx.save(); ctx.fillStyle = '#e7e4d3';
  if (flip && !S.noFlip) { ctx.translate(x + S.w * sc, y); ctx.scale(-sc, sc); } else { ctx.translate(x, y); ctx.scale(sc, sc); }
  S.draw(); ctx.restore();
}

