/* Sprites desenhados por caminho (iguais às artes de referência), usados em partida: na mão, arremessada, deslizando e no chão.
   Coordenadas da arma: x para a frente, a mão segura perto de x = 0. A tela ARMAS continua usando as silhuetas. */
{
  const INK = '#1b1b1f';
  const cp = (px, py) => [(px - 215) * .0415 - 9, (py - 510) * .0415];   // cutelo: pixel da arte -> unidades
  WEAPONS.cleaver.art = function () {
    const P = (...a) => a.length === 2 ? cp(a[0], a[1]) : null, M = (x, y) => ctx.moveTo(...cp(x, y)), L = (x, y) => ctx.lineTo(...cp(x, y));
    const C = (a, b, c, d, e, f) => ctx.bezierCurveTo(...cp(a, b), ...cp(c, d), ...cp(e, f)), Q = (a, b, c, d) => ctx.quadraticCurveTo(...cp(a, b), ...cp(c, d));
    ctx.lineJoin = 'round'; ctx.lineCap = 'round'; ctx.lineWidth = 1.1; ctx.strokeStyle = INK;
    // cabo de madeira com a ponta curva
    ctx.beginPath(); M(300, 445); L(690, 420); L(690, 515); L(440, 540); C(380, 560, 340, 600, 300, 610); C(250, 612, 222, 580, 220, 520); C(218, 480, 250, 445, 300, 445); ctx.closePath();
    ctx.fillStyle = '#5a3a24'; ctx.fill(); ctx.stroke();
    ctx.beginPath(); M(340, 462); L(675, 446); ctx.strokeStyle = '#7d5232'; ctx.lineWidth = .6; ctx.stroke();
    for (const [rx, ry] of [[318, 502], [466, 485], [620, 475]]) { ctx.beginPath(); ctx.arc(...cp(rx, ry), .75, 0, TAU); ctx.fillStyle = '#e3b94d'; ctx.fill(); ctx.lineWidth = .45; ctx.strokeStyle = '#2a1d10'; ctx.stroke(); }
    // lâmina larga de aço, com o furo no canto
    ctx.lineWidth = 1.1; ctx.strokeStyle = INK;
    ctx.beginPath(); M(697, 433); L(790, 426); L(900, 408); L(1040, 376); L(1170, 342); Q(1232, 322, 1262, 352); L(1278, 385); L(1318, 572); Q(1322, 580, 1300, 584); L(1085, 628); L(912, 655); L(745, 664); Q(730, 664, 727, 645); L(712, 545); L(700, 525); ctx.closePath();
    ctx.fillStyle = '#adadb0'; ctx.fill(); ctx.stroke();
    ctx.beginPath(); ctx.arc(...cp(1203, 402), 1.3, 0, TAU); ctx.fillStyle = INK; ctx.fill(); ctx.beginPath(); ctx.arc(...cp(1203, 402), .62, 0, TAU); ctx.fillStyle = '#f3f3f3'; ctx.fill();
  };
  WEAPONS.cleaver.bb = [-9.6, -8.4, 37.6, 7.1];
  WEAPONS.cleaver.parts = [[-9, 0, 46, 14, '#0000', 0]];   // só a medida (centralização); o desenho é o art
  WEAPONS.crowbar.art = function () {
    ctx.lineJoin = 'round'; ctx.lineCap = 'round';
    const path = () => { ctx.beginPath(); ctx.moveTo(-15.6, -6.6); ctx.bezierCurveTo(-12, -5, -10, 6.5, -7.5, 6.2); ctx.bezierCurveTo(-4.5, 6, -1.5, 3, 1.5, 0); ctx.lineTo(40.5, 0); ctx.quadraticCurveTo(44.5, 0, 47, 2.6); ctx.lineTo(51.7, 5.4); };
    path(); ctx.strokeStyle = INK; ctx.lineWidth = 6.4; ctx.stroke();           // contorno
    path(); ctx.strokeStyle = '#474c58'; ctx.lineWidth = 5; ctx.stroke();      // aço escuro
    ctx.beginPath(); ctx.moveTo(6, -1.3); ctx.lineTo(38, -1.3); ctx.strokeStyle = '#8b93a5'; ctx.lineWidth = .9; ctx.stroke();   // brilho da barra
    ctx.beginPath(); ctx.moveTo(-9.6, 5.1); ctx.lineTo(-7, 5.3); ctx.moveTo(44.5, 1.6); ctx.lineTo(48, 3.1); ctx.stroke();      // brilho na curva da garra e na ponta
    ctx.beginPath(); ctx.moveTo(-16.6, -7.4); ctx.lineTo(-13.4, -4.8); ctx.strokeStyle = INK; ctx.lineWidth = 1; ctx.stroke();  // entalhe em V da garra
  };
  WEAPONS.crowbar.bb = [-18.5, -9.8, 53.5, 9.8];
  WEAPONS.crowbar.parts = [[-16, 0, 68, 14, '#0000', 0]];
  WEAPONS.crowbar.extra = null;
}
/* Sprites de imagem (canivete e soco-inglês): PNG com fundo transparente embutido, desenhado no mesmo sistema do cutelo e do pé de cabra. */
{
  const loadImg = s => { const i = new Image(); i.src = s; return i; };
  const IMG_POCKET = loadImg('data:image/png;base64,');
  const IMG_KNUCK = loadImg('data:image/png;base64,');
  const put = (i, x, y, w, h) => { if (!i.complete || !i.naturalWidth) return; ctx.save(); ctx.imageSmoothingEnabled = true; ctx.imageSmoothingQuality = 'high'; ctx.drawImage(i, x, y, w, h); ctx.restore(); };
  WEAPONS.pocket.art = function () { put(IMG_POCKET, -8, -3.44, 41, 6.89); };   // lâmina para a frente (+x), cabo atrás
  WEAPONS.pocket.bb = [-8, -3.44, 33, 3.44];
  WEAPONS.pocket.parts = [[-8, 0, 41, 6, '#0000', 0]];   // só a medida (centralização e escala); o desenho é o art
  WEAPONS.pocket.extra = null;
  WEAPONS.knuckles.art = function () { put(IMG_KNUCK, 0, -10.40, 36, 20.81); };   // no chão e arremessado
  WEAPONS.knuckles.bb = [0, -10.40, 36, 10.40];
  WEAPONS.knuckles.handArt = function (skin) {   // no punho do personagem (vista de cima): barra sobre os dedos e quatro argolas com furo, preto como no desenho
    ctx.lineJoin = 'round'; ctx.lineWidth = 1; ctx.strokeStyle = 'rgba(0,0,0,.92)';
    ctx.fillStyle = '#2c2c32'; ctx.beginPath(); ctx.roundRect(3.6, -6, 3.4, 12, 1.4); ctx.fill(); ctx.stroke();
    for (const y of [-4.5, -1.5, 1.5, 4.5]) {
      ctx.fillStyle = '#2c2c32'; ctx.beginPath(); ctx.arc(7.6, y, 1.95, 0, TAU); ctx.fill(); ctx.stroke();
      ctx.fillStyle = skin || '#c58a63'; ctx.beginPath(); ctx.arc(7.6, y, .8, 0, TAU); ctx.fill(); ctx.lineWidth = .5; ctx.stroke(); ctx.lineWidth = 1;
    }
    ctx.fillStyle = 'rgba(255,255,255,.2)'; ctx.beginPath(); ctx.roundRect(4.1, -5.3, 1.1, 10.6, .55); ctx.fill();   // brilho
  };
}
/* TAMANHO REAL: len = comprimento da arma no mundo (unidades), proporcional ao tamanho real (cm). Vale na mão, no chão, arremessada e no deslize.
   A tela ARMAS e o HUD do canto inferior direito usam as silhuetas e não seguem isto. */
{
  const LEN = { glock: 28, beretta: 32, m1911: 32, python: 38, deagle: 40, sawed: 46,
    knuckles: 14, pocket: 26, butterfly: 26, cleaver: 38, bottle: 36, wrench: 46, crowbar: 72, sledge: 78 };   // mesmo tamanho na mão, no ar (arremessada) e no chão   // 10, 20, 22, 30, 30, 45, 76 e 90 cm
  for (const k in LEN) {
    const w = WEAPONS[k]; w.len = LEN[k]; if (w.knuckle) continue;   // soco-inglês: desenhado na mão do personagem, só o chão usa len
    const mn = Math.min(...w.parts.map(q => q[0])), mx = Math.max(...w.parts.map(q => q[0] + q[2])), v = LEN[k] / (mx - mn);
    w.vis = v; if (!w.melee) w.muzzle *= v;   // o cano acompanha a escala
  }
}
/* Ordem da tela ARMAS: brancas da mais fraca à mais forte, depois as de fogo da mais forte à mais fraca (as mais fracas dos dois tipos ficam juntas, ao lado do retângulo do meio) */
const WKEYS = [
  ...Object.keys(WEAPONS).filter(k => WEAPONS[k].melee).sort((a, b) => WEAPONS[a].dmg - WEAPONS[b].dmg),
  ...Object.keys(WEAPONS).filter(k => !WEAPONS[k].melee).sort((a, b) => WEAPONS[b].dmg * WEAPONS[b].pellets - WEAPONS[a].dmg * WEAPONS[a].pellets),
];
/* Sprite cartoon da arma deitada no chão (vista lateral, cano para a direita). Partes: [x, yCentro, largura, altura, cor, raio, giro] */
const _sbc = new WeakMap();
function sideBox(w) { let c = _sbc.get(w); if (!c) { c = sideBox0(w); _sbc.set(w, c); } return c; }
function sideBox0(w) { if (w.art) { const [x0, y0, x1, y1] = w.bb; return { x0, x1, y0, y1, w: x1 - x0, h: y1 - y0 }; }   // arma desenhada por caminho: usa a caixa dela
  const x0 = Math.min(...w.side.map(q => q[0])), x1 = Math.max(...w.side.map(q => q[0] + q[2])), y0 = Math.min(...w.side.map(q => q[1] - q[3] / 2)), y1 = Math.max(...w.side.map(q => q[1] + q[3] / 2)); return { x0, x1, y0, y1, w: x1 - x0, h: y1 - y0 }; }
function drawSide(w) {
  const B = sideBox(w); ctx.save(); ctx.translate(-(B.x0 + B.x1) / 2, -(B.y0 + B.y1) / 2);
  if (w.art) { w.art(); ctx.restore(); return; }
  for (const [x, cy, pw, ph, col, r, rot] of w.side) {
    ctx.save(); if (rot) { ctx.translate(x + pw / 2, cy); ctx.rotate(rot); ctx.translate(-(x + pw / 2), -cy); }
    ctx.beginPath(); ctx.roundRect(x, cy - ph / 2, pw, ph, r);
    ctx.fillStyle = col === '@' ? w.accent : col; ctx.fill();
    ctx.lineWidth = 1.3; ctx.lineJoin = 'round'; ctx.strokeStyle = 'rgba(0,0,0,.9)'; ctx.stroke();
    ctx.beginPath(); ctx.roundRect(x + 1, cy - ph / 2 + .6, Math.max(pw - 2, 1), Math.max(ph * .28, 1), r);
    ctx.fillStyle = 'rgba(255,255,255,.17)'; ctx.fill(); ctx.restore();
  }
  ctx.restore();
}

function drawWeapon(w) {
  if (w.art) { w.art(); return; }   // arma desenhada por caminho (cutelo, pé de cabra)
  for (const [x, cy, pw, ph, col, r] of w.parts) {
    ctx.beginPath(); ctx.roundRect(x, cy - ph / 2, pw, ph, r);
    ctx.fillStyle = col === '@' ? w.accent : col; ctx.fill();
    ctx.lineWidth = 1.1; ctx.strokeStyle = 'rgba(0,0,0,.85)'; ctx.stroke();
    ctx.beginPath(); ctx.roundRect(x + 1, cy - ph / 2 + .6, Math.max(pw - 2, 1), Math.max(ph * .3, 1), r);
    ctx.fillStyle = 'rgba(255,255,255,.17)'; ctx.fill();
  }
  if (w.extra) w.extra();
}

